/* eslint-disable security/detect-object-injection -- batchIndex is generated by the surrounding map and bounded by the embeddings array. */
import { randomUUID } from "crypto";
import { embedMany, ensureModel } from "@/lib/ai/service";
import {
  buildTsCall,
  formatTsMethodCall,
  rawTs,
  recordAstraClientCall,
} from "@/lib/astraClientLog";
import { DOCUMENT_BATCH_SIZE } from "@/lib/ingest/constants";
import { validateVectorDimension } from "@/lib/knowledge/dataApi/collectionConfig";
import type { CreateDataApiDb, DataApiKnowledgeConfig } from "@/lib/knowledge/dataApi/config";
import { resolveDataApiIngestContext } from "@/lib/knowledge/dataApi/ingestContext";
import type { KnowledgeDocumentIngestRequest } from "@/lib/knowledge/types";

export async function ingestDocumentIntoDataApi(
  request: KnowledgeDocumentIngestRequest,
  send: (event: Record<string, unknown>) => void,
  createDb: CreateDataApiDb,
  displayName: string
) {
  const { collectionName, sourceDocId, chunks, metadata, huggingfaceApiKey } = request;
  const { collection, collectionConfig, backend, backendHint } =
    await resolveDataApiIngestContext({
      config: request.config as DataApiKnowledgeConfig,
      collectionName,
      huggingfaceApiKey,
      createDb,
      displayName,
    });

  if (backend) {
    const prepareStart = Date.now();
    await ensureModel({
      backend,
      kind: "embed",
      allowPull: true,
      onProgress: (progress) => {
        send({
          type: "prepare",
          status: "running",
          provider: backend.provider,
          model: backend.embedModel,
          kind: "embed",
          message: progress.status,
          completed: progress.completed,
          total: progress.total,
          determinate: progress.determinate,
        });
      },
    }).then((result) => {
      send({
        type: "prepare",
        status: "complete",
        provider: backend.provider,
        model: result.model,
        kind: "embed",
        downloaded: result.downloaded,
        latencyMs: Date.now() - prepareStart,
      });
    });
  }

  send({
    type: "backend_info",
    useVectorize: collectionConfig.useVectorize,
    provider: backendHint.provider,
    model: backendHint.model,
  });

  for (let index = 0; index < chunks.length; index += DOCUMENT_BATCH_SIZE) {
    const batch = chunks.slice(index, index + DOCUMENT_BATCH_SIZE);

    let embeddings: number[][] | null = null;
    if (!collectionConfig.useVectorize) {
      if (!backend) {
        throw new Error("AI backend is required for non-vectorize collections");
      }
      embeddings = (
        await embedMany({
          backend,
          input: batch,
          allowPull: false,
          skipEnsure: true,
        })
      ).embeddings;
    }

    if (embeddings) {
      validateVectorDimension({
        collection: collectionName,
        expected: collectionConfig.vectorDimension,
        embeddings,
      });
    }

    const docs = batch.map((content, batchIndex) => {
      const chunkIndex = index + batchIndex;
      const doc: Record<string, unknown> = {
        _id: randomUUID(),
        content,
        metadata: {
          source_doc_id: sourceDocId,
          chunk_index: chunkIndex,
          ...metadata,
        },
      };

      if (collectionConfig.useVectorize) {
        doc.$vectorize = content;
      } else {
        doc.$vector = embeddings?.[batchIndex];
      }

      return doc;
    });

    send({
      type: "chunk_progress",
      processed: Math.min(index + DOCUMENT_BATCH_SIZE, chunks.length),
      total: chunks.length,
    });
    recordAstraClientCall({
      label: "Ingest Knowledge",
      code: buildTsCall(`db.collection(${JSON.stringify(collectionName)})`, [
        formatTsMethodCall("insertMany", [
          rawTs(`docsBatch /* ${docs.length} chunks */`),
        ]),
      ]),
    });
    await collection.insertMany(docs);
  }

  send({
    type: "backend_complete",
    provider: backendHint.provider,
    model: backendHint.model,
  });
}
